.game-shell::after { content: ""; position: absolute; z-index: 1; inset: 0; pointer-events: none; background: radial-gradient(ellipse at center, transparent 48%, rgba(4,7,6,.45) 100%); }

.hud { position: absolute; z-index: 3; inset: max(18px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) auto; display: grid; grid-template-columns: 1fr minmax(230px, 360px) 1fr; align-items: start; gap: 18px; pointer-events: none; }
.brand, .objective, .vitals { min-height: 60px; padding: 10px 14px; background: linear-gradient(135deg, rgba(15,19,17,.92), rgba(15,19,17,.67)); border: 1px solid var(--line); box-shadow: 0 8px 26px rgba(0,0,0,.25), inset 0 1px rgba(255,255,255,.035); backdrop-filter: blur(7px); }
.brand { display: flex; align-items: center; gap: 11px; justify-self: start; border-left: 2px solid var(--ember); }
.brand-mark { display: grid; place-items: center; width: 35px; height: 35px; color: var(--ember-bright); font-size: 23px; text-shadow: 0 0 14px rgba(255,154,67,.7); }
.brand small, .objective small { display: block; color: var(--muted); font-size: 8px; line-height: 1.4; letter-spacing: .24em; }
.brand strong { display: block; color: var(--paper); font-family: Impact, "Arial Narrow", sans-serif; font-size: 22px; line-height: 1; letter-spacing: .12em; }
.objective { justify-self: center; width: 100%; text-align: center; border-top: 2px solid rgba(255,154,67,.8); }
.objective strong { display: block; margin-top: 4px; color: var(--ember-bright); font-family: Impact, "Arial Narrow", sans-serif; font-size: 15px; letter-spacing: .09em; text-transform: uppercase; }
.vitals { justify-self: end; display: flex; align-items: center; gap: 18px; min-width: 184px; }
.hearts { color: #ef6851; font-size: 20px; letter-spacing: .13em; text-shadow: 0 0 12px rgba(238,76,52,.4); white-space: nowrap; }
.relic { color: #8d8978; font-family: Impact, "Arial Narrow", sans-serif; font-size: 12px; letter-spacing: .08em; white-space: nowrap; }
.relic span { margin-left: 3px; }
.relic.has-key { color: var(--ember-bright); text-shadow: 0 0 12px rgba(255,196,92,.35); }
.room-label { position: absolute; z-index: 3; top: 104px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 8px; padding: 6px 11px; color: rgba(240,223,184,.75); background: rgba(13,17,15,.55); border: 1px solid rgba(235,213,166,.1); font-family: Impact, "Arial Narrow", sans-serif; font-size: 10px; letter-spacing: .2em; white-space: nowrap; pointer-events: none; }
.room-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--ember); box-shadow: 0 0 10px var(--ember); }
.toast { position: absolute; z-index: 8; left: 50%; top: 23%; transform: translate(-50%,-8px); max-width: min(90vw, 520px); padding: 11px 17px; color: var(--paper); background: rgba(14,18,16,.94); border: 1px solid rgba(255,154,67,.65); box-shadow: 0 8px 30px rgba(0,0,0,.4), 0 0 24px rgba(255,154,67,.1); font-family: Impact, "Arial Narrow", sans-serif; font-size: 12px; letter-spacing: .14em; text-align: center; opacity: 0; pointer-events: none; transition: opacity .2s, transform .2s; }
.toast.show { opacity: 1; transform: translate(-50%,0); }
.controls-hint { position: absolute; z-index: 3; left: 50%; bottom: max(22px, env(safe-area-inset-bottom)); transform: translateX(-50%); display: flex; gap: 23px; padding: 9px 14px; color: rgba(240,223,184,.64); background: rgba(12,16,14,.72); border: 1px solid rgba(235,213,166,.11); font-family: Impact, "Arial Narrow", sans-serif; font-size: 9px; letter-spacing: .13em; white-space: nowrap; pointer-events: none; }
.controls-hint i { margin-left: 5px; color: var(--ember); font-style: normal; }
.controls-hint b { color: var(--ember-bright); font-weight: 400; }
.touch-controls { display: none; position: absolute; z-index: 4; left: max(18px, env(safe-area-inset-left)); right: max(18px, env(safe-area-inset-right)); bottom: max(18px, env(safe-area-inset-bottom)); justify-content: space-between; align-items: flex-end; pointer-events: none; touch-action: none; }
.dpad { display: grid; grid-template-columns: repeat(3, 48px); grid-template-rows: repeat(2, 48px); gap: 4px; pointer-events: auto; }
.dpad button, .fire-button, .use-button { appearance: none; display: grid; place-items: center; color: #f6dfb1; background: rgba(17,21,18,.78); border: 1px solid rgba(240,223,184,.32); box-shadow: inset 0 0 16px rgba(0,0,0,.3), 0 4px 16px rgba(0,0,0,.2); touch-action: none; user-select: none; }
.dpad button { width: 48px; height: 48px; border-radius: 7px; font-size: 16px; }
.dpad button:nth-child(1) { grid-column: 2; grid-row: 1; }
.dpad button:nth-child(2) { grid-column: 1; grid-row: 2; }
.dpad button:nth-child(3) { grid-column: 2; grid-row: 2; }
.dpad button:nth-child(4) { grid-column: 3; grid-row: 2; }
.dpad button:active, .fire-button:active, .use-button:active { background: rgba(116,58,22,.86); transform: scale(.96); }
.touch-actions { display: flex; align-items: flex-end; gap: 11px; pointer-events: auto; }
.fire-button { width: 76px; height: 76px; border-radius: 50%; color: #381a08; background: radial-gradient(circle at 35% 25%, #ffe29a, #ff9b43 58%, #9c441a); border-color: #ffce7e; box-shadow: 0 0 22px rgba(255,143,45,.28), inset 0 -7px 12px rgba(87,31,7,.35); font-size: 23px; }
.fire-button small { margin-top: -19px; font-size: 8px; font-weight: bold; letter-spacing: .14em; }
.use-button { width: 58px; height: 58px; border-radius: 50%; color: var(--ember-bright); font-family: Impact, "Arial Narrow", sans-serif; font-size: 12px; letter-spacing: .1em; }

.overlay { position: absolute; z-index: 10; inset: 0; display: grid; place-items: center; overflow-y: auto; padding: max(24px, env(safe-area-inset-top)) 20px max(24px, env(safe-area-inset-bottom)); background: radial-gradient(ellipse at 50% 40%, rgba(12,17,14,.64), rgba(8,11,10,.89) 68%, rgba(5,8,7,.96)); transition: opacity .35s ease, visibility .35s; }
.overlay::before { content: ""; position: fixed; inset: 0; pointer-events: none; opacity: .3; background: repeating-linear-gradient(135deg, transparent 0 84px, rgba(255,154,67,.04) 85px 86px); }
.overlay.hidden { display: grid !important; opacity: 0; visibility: hidden; pointer-events: none; }
.intro-card { position: relative; width: min(690px, 100%); padding: clamp(24px, 5vw, 48px) clamp(20px, 6vw, 64px); text-align: center; border: 1px solid rgba(232,207,156,.22); background: linear-gradient(145deg, rgba(27,32,27,.95), rgba(13,17,15,.97)); box-shadow: 0 26px 90px rgba(0,0,0,.65), inset 0 1px rgba(255,255,255,.06); }
.intro-card::before, .intro-card::after { content: ""; position: absolute; width: 42px; height: 42px; border-color: rgba(255,154,67,.72); border-style: solid; }
.intro-card::before { top: 8px; left: 8px; border-width: 1px 0 0 1px; }
.intro-card::after { right: 8px; bottom: 8px; border-width: 0 1px 1px 0; }
.eyebrow { display: flex; align-items: center; justify-content: center; gap: 11px; color: var(--ember); font-size: 9px; letter-spacing: .3em; text-transform: uppercase; }
.eyebrow span:first-child, .eyebrow span:last-child { width: 30px; height: 1px; background: linear-gradient(90deg, transparent, var(--ember)); }
.eyebrow span:last-child { transform: rotate(180deg); }
.crest { margin: 14px 0 3px; color: var(--ember-bright); font-size: 36px; line-height: 1; text-shadow: 0 0 24px rgba(255,153,62,.42); }
.intro-card h1 { margin: 0; color: var(--paper); font-family: Impact, Haettenschweiler, "Arial Narrow Bold", sans-serif; font-size: clamp(54px, 11vw, 100px); font-weight: 400; line-height: .9; letter-spacing: .055em; text-shadow: 0 4px 0 #5c3218, 0 12px 30px rgba(0,0,0,.7); }
.intro-card h2 { margin: 10px 0 18px; color: var(--ember); font-family: Impact, "Arial Narrow", sans-serif; font-size: clamp(15px, 3vw, 23px); font-weight: 400; letter-spacing: .38em; }
.intro-card p { max-width: 500px; margin: 0 auto 22px; color: rgba(240,223,184,.78); font-size: 13px; line-height: 1.7; }
.mission { display: flex; justify-content: center; gap: 8px; margin: 0 auto 24px; }
.mission span { flex: 1; padding: 10px 5px; color: var(--ember); border: 1px solid rgba(235,213,166,.13); background: rgba(255,255,255,.025); font-family: Impact, "Arial Narrow", sans-serif; font-size: 9px; letter-spacing: .12em; }
.mission b { display: block; margin-top: 5px; color: var(--paper); font-size: 9px; font-weight: 400; }
.start-button { appearance: none; min-width: 230px; padding: 13px 22px; color: #251307; background: linear-gradient(180deg, #ffd17f, #f3983f 58%, #c66a2c); border: 1px solid #ffdc9b; box-shadow: 0 0 32px rgba(255,145,54,.24), inset 0 -3px rgba(111,47,14,.2); font-family: Impact, "Arial Narrow", sans-serif; font-size: 19px; letter-spacing: .11em; cursor: pointer; transition: transform .15s, filter .15s, box-shadow .15s; }
.start-button span { padding-left: 9px; }
.start-button:hover { filter: brightness(1.1); transform: translateY(-2px); box-shadow: 0 0 42px rgba(255,145,54,.4); }
.start-button:active { transform: translateY(1px) scale(.99); }
.start-button:focus-visible, .dpad button:focus-visible, .fire-button:focus-visible, .use-button:focus-visible { outline: 2px solid #ffe4a9; outline-offset: 3px; }
.controls-copy { display: block; margin-top: 17px; color: rgba(240,223,184,.42); font-size: 8px; letter-spacing: .12em; }
.end-card .crest { color: var(--ember-bright); }

@media (max-width: 720px) {
  .hud { inset: max(10px, env(safe-area-inset-top)) max(10px, env(safe-area-inset-right)) auto; grid-template-columns: 1fr 1fr; gap: 7px; }
  .brand, .objective, .vitals { min-height: 48px; padding: 7px 9px; }
  .brand { gap: 6px; }
  .brand-mark { width: 25px; height: 25px; font-size: 18px; }
  .brand small, .objective small { font-size: 6px; letter-spacing: .18em; }
  .brand strong { font-size: 16px; }
  .objective { grid-column: 1 / -1; grid-row: 2; justify-self: center; width: min(70%, 280px); padding: 5px 8px; }
  .objective strong { margin-top: 2px; font-size: 11px; }
  .vitals { gap: 9px; min-width: 0; }
  .hearts { font-size: 16px; letter-spacing: .04em; }
  .relic { font-size: 9px; }
  .room-label { top: 105px; font-size: 8px; }
  .touch-controls { display: flex; }
  .controls-hint { display: none; }
  .toast { top: 27%; font-size: 10px; }
  .intro-card { padding: 24px 18px 22px; }
  .crest { margin-top: 10px; font-size: 28px; }
  .intro-card h1 { font-size: clamp(48px, 13vw, 76px); }
  .intro-card h2 { margin: 7px 0 13px; letter-spacing: .28em; }
  .intro-card p { margin-bottom: 15px; font-size: 11px; }
  .mission { gap: 4px; margin-bottom: 17px; }
  .mission span, .mission b { font-size: 7px; }
  .mission span { padding: 8px 2px; }
  .start-button { min-width: 200px; padding: 11px 16px; font-size: 16px; }
}
@media (max-height: 520px) and (orientation: landscape) {
  .hud { grid-template-columns: 1fr minmax(150px, 230px) 1fr; }
  .brand, .objective, .vitals { min-height: 42px; padding: 5px 8px; }
  .room-label { top: 62px; }
  .touch-controls { bottom: 10px; }
  .dpad { grid-template-columns: repeat(3, 38px); grid-template-rows: repeat(2, 38px); }
  .dpad button { width: 38px; height: 38px; }
  .fire-button { width: 62px; height: 62px; }
  .use-button { width: 48px; height: 48px; }
  .intro-card { padding: 15px 28px; }
  .intro-card .crest { margin: 5px 0 0; font-size: 24px; }
  .intro-card h1 { font-size: 50px; }
  .intro-card h2 { margin: 4px 0 7px; font-size: 15px; }
  .intro-card p { margin-bottom: 10px; font-size: 10px; }
  .mission { margin-bottom: 11px; }
  .mission span { padding: 5px; }
  .controls-copy { margin-top: 9px; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; } }
